package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;

public class UTF8JsonGenerator_writeNumber_TriageGen1Test {

    private ByteArrayOutputStream outputStream;
    private UTF8JsonGenerator generator;
    private IOContext ioContext;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        outputStream = new ByteArrayOutputStream();
        ioContext = IOContext.bootstrap();
        codec = mock(ObjectCodec.class);
        generator = new UTF8JsonGenerator(ioContext, 0, codec, outputStream);
    }

    /**
     * Helper to set the private field _cfgNumbersAsStrings using reflection
     * since it is not exposed in the public API but affects the logic.
     */
    private void setCfgNumbersAsStrings(boolean value) throws Exception {
        Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
        field.setAccessible(true);
        field.set(generator, value);
    }

    @Test
    public void testWriteNumber_WithNullValue() throws IOException {
        generator.writeNumber((BigDecimal) null);
        // When null is passed, _writeNull() is called. 
        // In Jackson, _writeNull typically writes the literal 'null'
        assertEquals("null", outputStream.toString());
    }

    @Test
    public void testWriteNumber_WithBigDecimal_WhenNumbersNotAsStrings() throws Exception {
        setCfgNumbersAsStrings(false);
        BigDecimal value = new BigDecimal("123.45");

        generator.writeNumber(value);

        // Logic calls writeRaw(_asString(value))
        assertEquals("123.45", outputStream.toString());
    }

    @Test
    public void testWriteNumber_WithBigDecimal_WhenNumbersAreAsStrings() throws Exception {
        setCfgNumbersAsStrings(true);
        BigDecimal value = new BigDecimal("123.45");

        generator.writeNumber(value);

        // If _cfgNumbersAsStrings is true, the code does nothing (empty block ;)
        // This means nothing is written to the output stream for the number itself
        assertEquals("", outputStream.toString());
    }

    @Test
    public void testWriteNumber_LargeBigDecimal() throws Exception {
        setCfgNumbersAsStrings(false);
        BigDecimal value = new BigDecimal("1000000000000000000000.0000000000000000000000001");

        generator.writeNumber(value);

        assertEquals("1000000000000000000000.0000000000000000000000001", outputStream.toString());
    }

    @Test
    public void testWriteNumber_Zero() throws Exception {
        setCfgNumbersAsStrings(false);
        BigDecimal value = BigDecimal.ZERO;

        generator.writeNumber(value);

        assertEquals("0", outputStream.toString());
    }

    @Test
    public void testWriteNumber_Negative() throws Exception {
        setCfgNumbersAsStrings(false);
        BigDecimal value = new BigDecimal("-50.25");

        generator.writeNumber(value);

        assertEquals("-50.25", outputStream.toString());
    }
}
